import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import {
  FaBrain,
  FaClock,
  FaExclamationTriangle,
  FaCalendarCheck,
  FaBookOpen
} from "react-icons/fa";
import PageHeader from "./PageHeader";
import DashboardCard from "./DashboardCard";
import SectionCard from "./SectionCard";
import "./dashboard.css";

function SmartPlannerAdvanced() {
  const userId = localStorage.getItem("user_id");

  const [planner, setPlanner] = useState({
    today: "",
    weakest_course: "",
    recommended_hours_today: 0,
    today_tasks_count: 0,
    today_tasks: [],
    all_tasks: []
  });

  const fetchPlanner = useCallback(() => {
    axios
      .get(`http://127.0.0.1:8000/smart-plan-advanced/${userId}`)
      .then((res) => setPlanner(res.data))
      .catch((err) => console.error("Planner fetch error:", err));
  }, [userId]);

  useEffect(() => {
    fetchPlanner();

    const handlePlannerUpdate = () => {
      fetchPlanner();
    };

    window.addEventListener("plannerUpdated", handlePlannerUpdate);

    return () => {
      window.removeEventListener("plannerUpdated", handlePlannerUpdate);
    };
  }, [fetchPlanner]);

  const getPriorityClass = (priority) => {
    if (priority === "High") return "badge badge-orange";
    if (priority === "Medium") return "badge badge-purple";
    return "badge badge-green";
  };

  return (
    <div>
      <PageHeader
        title="Smart Study Planner"
        subtitle="AI-like study planning based on your progress, pending work, and deadlines."
        action={
          <button className="btn btn-primary" onClick={fetchPlanner}>
            Refresh Planner
          </button>
        }
      />

      <div className="grid-4" style={{ marginBottom: "18px" }}>
        <DashboardCard
          icon={<FaBrain />}
          label="Weakest Subject"
          value={planner.weakest_course || "N/A"}
        />
        <DashboardCard
          icon={<FaClock />}
          label="Recommended Hours"
          value={`${planner.recommended_hours_today || 0} hrs`}
        />
        <DashboardCard
          icon={<FaExclamationTriangle />}
          label="Today's Tasks"
          value={planner.today_tasks_count || 0}
        />
        <DashboardCard
          icon={<FaCalendarCheck />}
          label="Today"
          value={planner.today || "--"}
        />
      </div>

      <SectionCard title="Today's Smart Plan">
        {planner.today_tasks.length === 0 ? (
          <p>No tasks for today.</p>
        ) : (
          planner.today_tasks.map((task, index) => (
            <div className="list-card" key={index}>
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  gap: "12px",
                  flexWrap: "wrap"
                }}
              >
                <div>
                  <h4 style={{ margin: "0 0 8px 0" }}>{task.course_title}</h4>
                  <div className="meta">Subject Code: {task.subject_code}</div>
                  <div className="meta">Task: {task.task}</div>
                  <div className="meta">Study Time: {task.daily_hours} hrs</div>
                  <div className="meta">
                    Deadline: {task.deadline || "No deadline"}
                  </div>
                </div>

                <div>
                  <span className={getPriorityClass(task.priority)}>
                    {task.priority}
                  </span>
                </div>
              </div>
            </div>
          ))
        )}
      </SectionCard>

      <div style={{ marginTop: "18px" }}>
        <SectionCard title="Upcoming Study Schedule">
          {planner.all_tasks.length === 0 ? (
            <p>No smart tasks generated.</p>
          ) : (
            planner.all_tasks.map((task, index) => (
              <div className="list-card" key={index}>
                <div
                  style={{
                    display: "flex",
                    gap: "16px",
                    alignItems: "center",
                    flexWrap: "wrap"
                  }}
                >
                  <div
                    style={{
                      minWidth: "120px",
                      fontWeight: "700",
                      color: "#6d28d9"
                    }}
                  >
                    {task.date}
                  </div>

                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: "600" }}>
                      <FaBookOpen style={{ marginRight: "8px", color: "#6d28d9" }} />
                      {task.course_title}
                    </div>
                    <div className="meta">{task.task}</div>
                    <div className="meta">
                      Progress: {task.progress_percent}% | Study: {task.daily_hours} hrs
                    </div>
                  </div>

                  <div>
                    <span className={getPriorityClass(task.priority)}>
                      {task.priority}
                    </span>
                  </div>
                </div>
              </div>
            ))
          )}
        </SectionCard>
      </div>
    </div>
  );
}

export default SmartPlannerAdvanced;
